import React, { useState, useEffect } from 'react';

/* ── SVG icons ── */
const IconHome = () => (
  <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor"
    strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M3 9.5L12 3l9 6.5V20a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V9.5z"/>
    <polyline points="9 21 9 12 15 12 15 21"/>
  </svg>
);
const IconAI = () => (
  <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor"
    strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <rect x="2" y="7" width="20" height="14" rx="2"/>
    <path d="M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2"/>
    <line x1="12" y1="12" x2="12" y2="16"/>
    <line x1="10" y1="14" x2="14" y2="14"/>
  </svg>
);
const IconServices = () => (
  <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor"
    strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <rect x="2" y="7" width="20" height="14" rx="2"/>
    <path d="M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2"/>
  </svg>
);
const IconAbout = () => (
  <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor"
    strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="10"/>
    <line x1="12" y1="16" x2="12" y2="12"/>
    <line x1="12" y1="8" x2="12.01" y2="8"/>
  </svg>
);
const IconGlobe = () => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#777"
    strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="10"/>
    <line x1="2" y1="12" x2="22" y2="12"/>
    <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/>
  </svg>
);

const navLinks = [
  { label: 'Accueil',    Icon: IconHome,     active: true  },
  { label: 'Djamano ai', Icon: IconAI,       active: false },
  { label: 'Services',   Icon: IconServices, active: false },
  { label: 'A propos',   Icon: IconAbout,    active: false },
];

const Navbar = () => {
  const [scrolled, setScrolled] = useState(false);
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 10);
    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const s = {
    nav: {
      position: 'fixed', top: 0, left: 0, right: 0, zIndex: 1000,
      background: 'rgba(255,255,255,0.97)',
      backdropFilter: 'blur(12px)',
      borderBottom: '1px solid #f0f0f0',
      boxShadow: scrolled ? '0 2px 24px rgba(0,0,0,0.07)' : 'none',
      transition: 'box-shadow .3s',
      fontFamily: 'Poppins, sans-serif',
    },
    inner: {
      maxWidth: 1200, margin: '0 auto', padding: '0 32px',
      height: 66, display: 'flex', alignItems: 'center', justifyContent: 'space-between',
    },
    /* Logo */
    logo: {
      display: 'flex', alignItems: 'center', gap: 6,
      fontFamily: 'Poppins, sans-serif', fontWeight: 700, fontSize: 20,
      color: '#111', letterSpacing: '-0.3px', textDecoration: 'none',
    },
    logoCircle: {
      width: 32, height: 32,
      borderRadius: '50%',
      border: '2.5px solid #FF5A00',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      flexShrink: 0,
    },
    logoCircleSvg: { width: 16, height: 16 },
    logoText: { fontStyle: 'italic', letterSpacing: '-0.5px' },

    /* Links */
    links: { display: 'flex', alignItems: 'center', gap: 4 },
    link: (active) => ({
      display: 'flex', alignItems: 'center', gap: 7,
      padding: '9px 18px', borderRadius: 10,
      fontSize: 14, fontWeight: active ? 600 : 500,
      color: active ? '#FF5A00' : '#444',
      background: active ? '#ffffff' : 'transparent',
      cursor: 'pointer', transition: 'all .2s',
      fontFamily: 'Poppins, sans-serif',
      border: 'none',
    }),

    /* Right */
    right: { display: 'flex', alignItems: 'center' },
    globe: {
      width: 40, height: 40, borderRadius: 10,
      border: '1.5px solid #e8e8e8', background: '#fff',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      cursor: 'pointer',
    },
  };

  return (
    <nav style={s.nav}>
      <div style={s.inner}>
        {/* Logo */}
        <a style={s.logo} href="#">
          <div style={s.logoCircle}>
            {/* Stylized D letter */}
            <svg viewBox="0 0 18 18" fill="none" style={s.logoCircleSvg}>
              <path d="M4 3h5c3.3 0 6 2.7 6 6s-2.7 6-6 6H4V3z"
                stroke="#FF5A00" strokeWidth="2" fill="none"
                strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          </div>
          <span style={s.logoText}>Djamano</span>
        </a>

        {/* Nav links */}
        <div style={s.links}>
          {navLinks.map(({ label, Icon, active }) => (
            <button key={label} style={s.link(active)}>
              <Icon />
              {label}
            </button>
          ))}
        </div>

        {/* Globe */}
        <div style={s.right}>
          <div style={s.globe}><IconGlobe /></div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
